    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint balBefore = address(c).balance;
        uint potBefore = c.pot();
        require(potBefore <= balBefore);

        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint potAfter = c.pot();

        if (reverted) {
            assert(amount != 10 && address(c).balance == balBefore);
        } else if (potAfter == 0) {
            // win: entire pot (potBefore + 10, minus 1 fee returning to us) paid out
            assert(amount == 10 && address(c).balance + potBefore == balBefore + 10);
        } else {
            // loss: pot grows by exactly the ticket amount, balance too
