contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount == 10);
        require(address(this).balance >= amount + 10);

        // First play may win (pot -> 0, fee -> bank) or lose (pot -> 10);
        // either way the bank is paid the fee if the pot was emptied.
        c.play{value: amount}();

        uint potBefore = c.pot();
        uint bankBefore = address(this).balance;

        c.play{value: 10}();

        uint potAfter = c.pot();

        // If the second play won, the pot was emptied and the bank got exactly the 1-wei fee.
        // If the pot was empty before, the win path reverts (underflow), so pot stays nonzero.
        assert(potAfter != 0 || address(this).balance == bankBefore + 1);
    }

    receive() external payable {}
}

