    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount == 10);
        require(address(this).balance >= amount);
        require(c.pot() == 0);

        uint bankBefore = address(this).balance;

        c.play{value: amount}();

        uint potAfter = c.pot();
        uint bankAfter = address(this).balance;

        // Losing play: pot becomes the 10-wei ticket, bank balance untouched.
        // Winning play: the 1-wei fee paid to the bank is exactly offset by
        // the pot minus fee returned to the player (same contract), so the
        // balance is net unchanged (input 10 minus 10 paid out), pot is 0.
        assert(
            (potAfter == 10 && bankAfter == bankBefore) ||
            (potAfter == 0 && bankAfter == bankBefore)
        );
    }

    receive() external payable {}
}

